const itemTypeId = options.currentTarget.itemTypeId;
if (!itemTypeId) {
	return Promise.resolve();
}

const itemType = options.itemType;
const itemTypeName = itemType.name;
const label = itemType['label_plural'] || itemTypeName;
const image = itemType['open_icon'] || '../images/DefaultItemType.svg';	
const itemTypeData = {
	image,
	id: itemTypeId,
	label
};

const layout = options.getLayout();
const sidebar = layout.navigationPanel.tabs;
const sidebarTabs = sidebar.tabs;
const sidebarTabsCount = sidebarTabs.length;
const lastTabId = sidebarTabs[sidebarTabsCount - 1];
const { favorites } = options.getProps();
const favoriteTab = favorites[lastTabId];
let favoriteOrder = 0;
if (!favoriteTab) {
	favoriteOrder = 128;
} else if (favoriteTab.favoriteOrder){
	favoriteOrder = parseInt(favoriteTab.favoriteOrder) + 128;
} else {
	favoriteOrder = 128 * sidebarTabsCount;
}

const id = aras.IomInnovator.getNewID();

return options.favorites.add('ItemType', {
	contextType: itemTypeName,
	id: id,
	additional_data: itemTypeData,
	favoriteOrder
});
